import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class ClassX {
    /**
     * Verilen anahtar ve iv için bir parmak izi oluşturun.
     *
     * @param anahtar Şifreleme için kullanılan anahtar.
     * @param iv      Şifreleme için kullanılan iv.
     * @return Anahtar ve IV'nin birleştirilmiş bir SHA-256 parmak izi (Base64 kodlu).
     * @throws NoSuchAlgorithmException Eğer SHA-256 algoritması mevcut değilse.
     */
    public String createFingerprint(byte[] anahtar, byte[] iv) throws NoSuchAlgorithmException {
        // Anahtar ve IV'yi birleştirin
        byte[] combined = new byte[anahtar.length + iv.length];
        System.arraycopy(anahtar, 0, combined, 0, anahtar.length);
        System.arraycopy(iv, 0, combined, anahtar.length, iv.length);

        // Birleştirilmiş verinin SHA-256 özetini hesaplayın
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(combined);

        // Özeti Base64 olarak kodlayın
        return Base64.getEncoder().encodeToString(hash);
    }
}
