    public void encryptAndSendMessage(byte[] secret_key, OutputStream channel, byte[] message) throws Exception {
        // Generate a random IV for CBC mode
        byte[] iv = new byte[16]; // AES block size is 16 bytes
        new java.security.SecureRandom().nextBytes(iv);
        IvParameterSpec ivSpec = new IvParameterSpec(iv);

        // Create SecretKeySpec
        SecretKeySpec keySpec = new SecretKeySpec(secret_key, "AES");

        // Get Cipher instance for AES in CBC mode with PKCS5 padding
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

        // Initialize the cipher for encryption
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);

        // Encrypt the message
        byte[] encryptedMessage = cipher.doFinal(message);

        // Write the IV to the channel first, so the recipient can decrypt
        channel.write(iv);

        // Write the encrypted message to the channel
        channel.write(encryptedMessage);

        // Flush the channel to ensure all data is sent
        channel.flush();
    }
