        // Create a SecretKeySpec from the secret key
        SecretKeySpec secretKeySpec = new SecretKeySpec(secret_key, "AES");

        // Generate a random 16-byte IV for AES
        byte[] iv = new byte[16]; // 16 bytes for AES block size
        new java.security.SecureRandom().nextBytes(iv);
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);

        // Get an AES cipher instance
        // Using AES/CBC/PKCS5Padding as a standard secure mode
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

        // Initialize the cipher for encryption mode with the key and IV
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

        // Encrypt the message
        byte[] encryptedMessage = cipher.doFinal(message);

        // Send the IV first, so the recipient can decrypt
        channel.write(iv);
        // Then send the encrypted message
        channel.write(encryptedMessage);
        channel.flush();
    }
