import java.util.regex.*;

public class ClassX {
    /**
     * Controleer of het 'www.example.com/' of 'beta.example.com/' bevat.
     * 
     * @param query: De te controleren query
     * @return: 'Zoekresultaten voor: <query>' als de query geldig is, 'Geen resultaten gevonden voor: <query>' anders
     */
    public String checkQuery(String query) {
        // Regular expression om te controleren op 'www.example.com/' of 'beta.example.com/'
        // De regex ^.*(www|beta)\\.example\\.com/.*$ betekent:
        // ^.*     - start van de string, gevolgd door nul of meer willekeurige karakters
        // (www|beta) - 'www' of 'beta'
        // \\.     - een letterlijke punt (moet escaped worden)
        // example\\.com/ - 'example.com/'
        // .*$     - gevolgd door nul of meer willekeurige karakters tot het einde van de string
        String regex = "^.*(www|beta)\\.example\\.com/.*$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(query);

        if (matcher.matches()) {
            return "Zoekresultaten voor: " + query;
        } else {
            return "Geen resultaten gevonden voor: " + query;
        }
    }
}
