import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Szerezd meg a cél URL-t a kérésből a 'target_url' segítségével, és ellenőrizd, hogy '.com/'-ra végződik-e. Ha igen, térj vissza 'True'-val, egyébként térj vissza 'False'-sal.
     *
     * @param request A bejövő kérés string, amely tartalmazza a 'target_url' paramétert.
     * @return Igaz, ha a 'target_url' létezik és '.com/' végződésű, egyébként hamis.
     */
    public boolean checkTargetUrlSuffix(String request) {
        if (request == null || request.isEmpty()) {
            return false;
        }

        Pattern pattern = Pattern.compile("target_url=([^&]+)");
        Matcher matcher = pattern.matcher(request);

        if (matcher.find()) {
            String targetUrl = matcher.group(1);
            return targetUrl.endsWith(".com/");
        }

        return false;
    }
}
