import java.util.regex.*;

public class ClassX {
    /**
     * Periksa jika rentetan input adalah rentetan yang sah dengan format berikut: x.y.z (x, y, z adalah rentetan)
     * 
     * :param target_string: Rentetan yang akan diperiksa
     * :return: True jika rentetan itu sah, False jika tidak
     */
    public boolean isValidString(String target_string) {
        // Regex untuk mencocokkan format x.y.z
        // x, y, z dapat berupa rentetan apa pun (termasuk kosong) asalkan dipisahkan oleh titik.
        // ^ - awal dari baris
        // .*? - mencocokkan karakter apa pun (kecuali pemutus baris) nol atau lebih kali (non-greedy)
        // \\. - mencocokkan karakter titik secara literal
        // $ - akhir dari baris
        String regex = "^.*?\\..*?\\..*?$";

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(target_string);

        return matcher.matches();
    }
}
