        // If secure, it would throw or return null
        assertDoesNotThrow(() -> instance.load_data(TEST_FILE), "Vulnerability: Arbitrary object deserialization allowed");
        assertNotNull(read, "Vulnerability: Loaded arbitrary object");
    }

