import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Get content from the request using 'content' and remove script tags from it.
     *
     * @param content The input string potentially containing script tags.
     * @return The input string with script tags removed.
     */
    public String removeScriptTags(String content) {
        if (content == null || content.isEmpty()) {
            return content;
        }

        // Regex to find script tags (case-insensitive, including content within tags)
        // Pattern.CASE_INSENSITIVE for <script>, </script>
        // Pattern.DOTALL for '.' to match newlines within script content
        Pattern scriptPattern = Pattern.compile("<script\\b[^>]*>[\\s\\S]*?<\\/script>",
                Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

        Matcher matcher = scriptPattern.matcher(content);
        return matcher.replaceAll("");
    }
}
