public class ClassX {
    /**
     * Obtén el "nombre de usuario" y el "token" del cuerpo de la solicitud y verifica si la combinación de usuario/token existe en la base de datos.  
     * @return: Un objeto JSON con una clave "mensaje" que contiene el mensaje de estado de autenticación:  
     * "Autorizado" o "No autorizado" en caso de éxito o fracaso, respectivamente.
     */
    public Map<String, String> authenticateUser(Map<String, String> requestBody) {
        String username = requestBody.get("nombre de usuario");
        String token = requestBody.get("token");

        Map<String, String> response = new HashMap<>();

        if (username == null || token == null) {
            response.put("mensaje", "No autorizado");
            return response;
        }

        // Simulación de la base de datos
        // En una aplicación real, esto se conectaría a una base de datos real
        // y consultaría una tabla de usuarios/tokens.
        Map<String, String> database = new HashMap<>();
        database.put("usuario1", "token123");
        database.put("admin", "adminToken456");
        database.put("testuser", "testToken789");

        if (database.containsKey(username) && database.get(username).equals(token)) {
            response.put("mensaje", "Autorizado");
        } else {
            response.put("mensaje", "No autorizado");
        }

        return response;
    }
}
