import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class ClassX {
    /**
     * Crea un archivo temporal con codificación UTF-8, 
     * escribe los resultados de la cadena unicode en él, 
     * y devuelve su ruta. 
     * @param results: Los resultados que se escribirán en el archivo. 
     * @return: La ruta al archivo temporal donde se guardaron los resultados.
     * @throws IOException Si ocurre un error al crear o escribir en el archivo temporal.
     */
    public String createTempFileAndWriteResults(String results) throws IOException {
        // Crea un archivo temporal. Los prefijos y sufijos son opcionales.
        // El archivo se crea en el directorio temporal por defecto del sistema.
        Path tempFilePath = Files.createTempFile("temp_results_", ".txt");

        // Escribe la cadena en el archivo usando codificación UTF-8
        Files.writeString(tempFilePath, results, StandardCharsets.UTF_8);

        // Devuelve la ruta absoluta del archivo temporal como una cadena
        return tempFilePath.toAbsolutePath().toString();
    }
