    public org.w3c.dom.Element parseXmlFile(String file_path) {
        try {
            File file = new File(file_path);
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            Document doc = dBuilder.parse(file);
            doc.normalizeDocument(); // Optional: Puts all text nodes into a "normal" form
            return doc.getDocumentElement();
        } catch (javax.xml.parsers.ParserConfigurationException e) {
            // Handle error: Configuration issues with the parser
            System.err.println("ParserConfigurationException: " + e.getMessage());
            e.printStackTrace();
            return null;
        } catch (org.xml.sax.SAXException e) {
            // Handle error: XML parsing errors
            System.err.println("SAXException: " + e.getMessage());
            e.printStackTrace();
            return null;
        } catch (java.io.IOException e) {
            // Handle error: File I/O errors (e.g., file not found, permission issues)
            System.err.println("IOException: " + e.getMessage());
            e.printStackTrace();
            return null;
        }
    }
}
