public class ClassX {
    /**
     * Crea un parser XML e analizza il file restituendo l'elemento radice.
     * @param file_path: Il percorso del file XML da analizzare.
     * @return: L'elemento radice del file XML.
     * @throws ParserConfigurationException Se non è possibile ottenere un parser che soddisfi la configurazione richiesta.
     * @throws SAXException Se si verifica un errore generico o un avviso SAX durante l'analisi.
     * @throws IOException Se si verifica un errore I/O durante l'analisi.
     */
    public Document parseXmlFile(String file_path) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(new File(file_path));
        document.getDocumentElement().normalize(); // Optional: normalize the document
        return document;
    }
}
