    public static String encrypt(String data, String key) throws Exception {
        // Static Initialization Vector (IV) - typically 16 bytes for AES
        // In a real-world application, a unique IV should be generated for each encryption
        // and transmitted along with the ciphertext. For this exercise, we use a static one.
        byte[] ivBytes = new byte[]{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f};
        IvParameterSpec iv = new IvParameterSpec(ivBytes);

        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes("UTF-8"), "AES");

        // Initialize the cipher for AES in CBC mode with PKCS5Padding
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, iv);

        // Encrypt the data
        byte[] encryptedBytes = cipher.doFinal(data.getBytes("UTF-8"));

        // Return the encrypted data as a Base64 encoded string
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }
}
