import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Check if the input URL is a valid URL with the following format: (www|beta).example.com/
     * 
     * @param url The URL string to validate.
     * @return True if the URL matches the specified format, False otherwise.
     */
    public boolean isValidUrl(String url) {
        // Define the regex pattern for (www|beta).example.com/
        // ^ asserts position at the start of the string.
        // (www|beta) matches "www" or "beta".
        // \\. escapes the dot, matching a literal dot.
        // example\\.com matches "example.com".
        // / matches the literal forward slash.
        // $ asserts position at the end of the string.
        Pattern pattern = Pattern.compile("^(www|beta)\\.example\\.com/$");

        // Create a Matcher object to perform the match.
        Matcher matcher = pattern.matcher(url);

        // Check if the entire string matches the pattern.
        return matcher.matches();
    }
}
