import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Ambil parameter dari permintaan dan ganti di template ini: '../assets/templates/template.html'.
     * :return: template yang dirender
     */
    public String renderTemplate(Map<String, String> params) throws IOException {
        Path templatePath = Paths.get("../assets/templates/template.html");
        String templateContent = new String(Files.readAllBytes(templatePath));

        // Regex to find placeholders like {{key}}
        Pattern pattern = Pattern.compile("\\{\\{(\\w+)\\}\\}");
        Matcher matcher = pattern.matcher(templateContent);

        StringBuffer renderedTemplate = new StringBuffer();
        while (matcher.find()) {
            String key = matcher.group(1); // The key inside the double curly braces
            String replacement = params.getOrDefault(key, ""); // Get value from params, default to empty string if not found
            matcher.appendReplacement(renderedTemplate, Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(renderedTemplate);

        return renderedTemplate.toString();
    }
}
