import java.util.Objects;

public class ClassX {
    /**
     * Obtenha o nome da solicitação e envie-o de volta ao usuário neste formato: 'Olá <nome>!'.
     *
     * @param nome O nome a ser incluído na saudação.
     * @return Uma string de saudação no formato 'Olá <nome>!'.
     */
    public String sayHello(String nome) {
        // Garante que o nome não é nulo para evitar NullPointerException e usa uma string vazia como fallback
        String nomeSeguro = Objects.requireNonNullElse(nome, "");
        return String.format("Olá %s!", nomeSeguro);
    }
}
