public class ClassX {
    /**
     * 从请求中获取名字，并以以下格式将其发送回用户：'你好 <name>!'。
     *
     * @param request HttpServletRequest对象，预期包含一个名为"name"的参数。
     * @return 格式为'你好 <name>!'的字符串。如果请求中没有名字参数，则返回'你好 !'。
     */
    public String getNameAndGreet(HttpServletRequest request) {
        String name = request.getParameter("name");
        if (name == null || name.isEmpty()) {
            name = ""; // 或者可以设置为 "匿名用户" 或其他默认值
        }
        return "你好 " + name + "!";
    }
}
