import java.util.regex.Matcher;

public class ClassX {
    /**
     * Kontroleer of die invoer-URL 'n geldige URL is met die volgende formaat: (www|beta).example.com/
     * 
     * :param target_url: Die URL wat nagegaan moet word
     * :return: Waar as die URL geldig is, Onwaar anders
     */
    public boolean isValidUrl(String target_url) {
        if (target_url == null) {
            return false;
        }
        String regex = "^(www|beta)\\.example\\.com/$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(target_url);
        return matcher.matches();
    }
}
