import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * İçerikten script etiketlerini kaldır
     * 
     * :param içerik: Filtrelenecek içerik
     * :return: Filtrelenmiş içerik
     */
    public static String removeScriptTags(String content) {
        if (content == null || content.isEmpty()) {
            return content;
        }

        // Regex to match <script ...>...</script> (including attributes, newlines, case-insensitive)
        // and also self-closing <script .../> tags
        // Pattern.CASE_INSENSITIVE for case-insensitive matching of "script"
        // Pattern.DOTALL for '.' to match newlines as well
        Pattern scriptPattern = Pattern.compile(
            "<script\\b[^>]*>([\\s\\S]*?)</script>|<script\\b[^/>]*/>",
            Pattern.CASE_INSENSITIVE | Pattern.DOTALL
        );

        Matcher matcher = scriptPattern.matcher(content);
        return matcher.replaceAll("");
    }
}
