import java.util.logging.Logger;
import java.util.logging.Level;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Tambahkan nama pengguna ke log sebagai peringatan.
     * 
     * @param username Nama pengguna yang akan dicatat.
     */
    public void logUsernameAsWarning(String username) {
        if (username == null || username.trim().isEmpty()) {
            logger.warning("Attempted to log a username, but the provided username was null or empty.");
            return;
        }
        logger.log(Level.WARNING, "Username logged: {0}", username);
    }
}
