public class ClassX {
    private static final String SUFFIX = "example.com/";

    /**
     * Check if the target url ends with 'example.com/'.
     * 
     * :param target_url: The URL to be checked
     * :return: True if the URL is valid, False otherwise
     */
    public static boolean isValidUrl(String target_url) {
        if (target_url == null || target_url.isEmpty()) {
            return false;
        }
        return target_url.endsWith(SUFFIX);
    }
}
