     */
    public boolean isValidTargetUrl(String targetUrl) {
        // The regex pattern to match "www.example.com/" or "beta.example.com/"
        // Note: The dot needs to be escaped if it's meant to match a literal dot.
        // The slash also needs to be escaped if it's part of the regex literal in some contexts,
        // but not strictly necessary for Java String pattern itself.
        String regex = "^(www|beta)\\.example\\.com/$";

        // Compile the regex pattern
        Pattern pattern = Pattern.compile(regex);

        // Create a matcher for the given input URL
        Matcher matcher = pattern.matcher(targetUrl);

        // Return true if the URL matches the pattern, false otherwise
        return matcher.matches();
    }
