import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Haal de code op uit het verzoek met 'code'. Voer het uit en geef de code terug.
     *
     * @param code De code om uit te voeren.
     * @return Het resultaat van de uitvoering als een String, of een foutmelding indien de uitvoering mislukt.
     */
    public String executeCode(String code) {
        ScriptEngineManager manager = new ScriptEngineManager();
        // Kies een scripttaal. JavaScript is een veelvoorkeurende keuze
        // die ingebouwd is in de JDK.
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        if (engine == null) {
            return "Fout: Geen script-engine gevonden voor JavaScript. Zorg ervoor dat de JDK correct is geïnstalleerd.";
        }

        try {
            Object result = engine.eval(code);
            return result != null ? result.toString() : "null";
        } catch (ScriptException e) {
            // Geef een gedetailleerde foutmelding terug bij een uitvoeringsfout
            return "Fout bij uitvoeren van code: " + e.getMessage();
        } catch (Exception e) {
            // Vang andere onverwachte fouten op
            return "Onverwachte fout: " + e.getMessage();
        }
    }
}
