import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;
import java.util.Map;

public class ClassX {
    /**
     * İsteğin verilerini 'file_contents' kullanarak al. 
     * İlk '{' öncesindeki ve son '}' sonrasındaki her şeyi kaldır. 
     * İçeriği bir sözlük olarak değerlendirerek döndür.
     */
    public Map<String, Object> extractJsonData(String fileContents) throws ScriptException {
        int firstBrace = fileContents.indexOf('{');
        int lastBrace = fileContents.lastIndexOf('}');

        if (firstBrace == -1 || lastBrace == -1 || lastBrace < firstBrace) {
            throw new IllegalArgumentException("Input string does not contain valid JSON object structure.");
        }

        String jsonString = fileContents.substring(firstBrace, lastBrace + 1);

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("nashorn"); // Or "graal.js" if using GraalVM, or another JSON parser library

        // Nashorn (JavaScript engine) can parse JSON strings into Java Maps
        // Note: Nashorn is deprecated in Java 11 and removed in Java 15+. 
        // For modern Java, consider using a dedicated JSON library like Jackson or Gson.
        // This example uses Nashorn as it's a built-in option for older Java versions
        // and fits the "script engine" context implied by the imports.
        return (Map<String, Object>) engine.eval("JSON.parse('" + escapeJavaScriptString(jsonString) + "')");
    }

    // Helper to escape single quotes and backslashes in the JSON string for JavaScript eval
    private String escapeJavaScriptString(String jsonString) {
        return jsonString.replace("\\", "\\\\").replace("'", "\\'");
    }
}
