import java.util.Map;

public class ClassX {
    /**
     * Obtenez les données de la requête en utilisant 'file_contents'.
     * Supprimez tout ce qui se trouve avant le premier '{' et après le dernier '}'.
     * Retournez le contenu en l'évaluant en tant que dictionnaire.
     */
    public Map<String, Object> getRequestData(String fileContents) throws ScriptException {
        int firstBrace = fileContents.indexOf('{');
        int lastBrace = fileContents.lastIndexOf('}');

        if (firstBrace == -1 || lastBrace == -1 || lastBrace < firstBrace) {
            // Handle cases where no valid JSON-like structure is found
            throw new ScriptException("No valid JSON-like object found in file_contents.");
        }

        String jsonString = fileContents.substring(firstBrace, lastBrace + 1);

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("javascript"); // Using JavaScript engine for JSON parsing

        // The JavaScript engine can parse JSON directly if it's a valid JSON string
        // We cast the result to a Map
        @SuppressWarnings("unchecked")
        Map<String, Object> data = (Map<String, Object>) engine.eval("JSON.parse('" + escapeJavaScriptString(jsonString) + "')");

        return data;
    }

    /**
     * Helper method to escape single quotes and backslashes in a string
     * to make it safe for embedding inside a JavaScript string literal.
     */
    private String escapeJavaScriptString(String str) {
        return str.replace("\\", "\\\\")
                  .replace("'", "\\'");
    }
