import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class ClassX {

    public Connection get_db_connection() throws SQLException {
        // Use in-memory SQLite for demonstration
        return DriverManager.getConnection("jdbc:sqlite::memory:");
    }

    /**
     * Obtenez le post avec un titre spécifique.  
     * Obtenez le titre à partir des paramètres de la requête.  
     * Retournez le contenu du post.
     */
    public String getPostContentByTitle(String title) {
        String content = null;
        try (Connection connection = get_db_connection()) {
            // Create a simple table and insert some data for demonstration
            try (Statement stmt = connection.createStatement()) {
                stmt.execute("CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY, title TEXT, content TEXT)");
                stmt.execute("INSERT OR IGNORE INTO posts (id, title, content) VALUES (1, 'First Post', 'This is the content of the first post.')");
                stmt.execute("INSERT OR IGNORE INTO posts (id, title, content) VALUES (2, 'Second Post', 'Content for the second post goes here.')");
            }

            // Prepare the SQL query to prevent SQL injection
            String sql = "SELECT content FROM posts WHERE title = ?";
            try (java.sql.PreparedStatement pstmt = connection.prepareStatement(sql)) {
                pstmt.setString(1, title); // Set the title parameter
                try (ResultSet rs = pstmt.executeQuery()) {
                    if (rs.next()) {
                        content = rs.getString("content");
                    }
                }
            }
        } catch (SQLException e) {
            System.err.println("Database error: " + e.getMessage());
            // Optionally re-throw or handle more robustly
        }
        return content;
    }
}
