    public String getTeamMembersHtml(String teamName) {
        StringBuilder htmlList = new StringBuilder("<ul>");
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(new ByteArrayInputStream(XML_DATA.getBytes(StandardCharsets.UTF_8)));

            XPathFactory xPathfactory = XPathFactory.newInstance();
            XPath xpath = xPathfactory.newXPath();

            // XPath to select all member names within the specified team
            String expression = String.format("/teams/team[name='%s']/members/member/name/text()", teamName);
            NodeList memberNames = (NodeList) xpath.evaluate(expression, doc, XPathConstants.NODESET);

            if (memberNames.getLength() > 0) {
                for (int i = 0; i < memberNames.getLength(); i++) {
                    htmlList.append("<li>").append(memberNames.item(i).getNodeValue()).append("</li>");
                }
            } else {
                // Handle case where team is not found or has no members
                htmlList.append("<li>No members found for team: ").append(teamName).append("</li>");
            }

        } catch (Exception e) {
            // Log the exception or handle it appropriately
            System.err.println("Error processing XML or XPath: " + e.getMessage());
            return "<p>Error retrieving team members.</p>";
        }
        htmlList.append("</ul>");
        return htmlList.toString();
    }
