import java.util.logging.Logger;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Haal de gebruikersnaam uit het verzoek met 'naam' en log het als het geen admin is.
     * @param request Een object dat de aanvraag vertegenwoordigt en waarvan de gebruikersnaam kan worden opgehaald.
     *                We gaan ervan uit dat het een methode `getParameter(String name)` heeft.
     * @return De gebruikersnaam, of null als deze niet gevonden is.
     */
    public String getAndLogUsernameIfNotAdmin(Request request) {
        String username = request.getParameter("naam");

        if (username != null && !username.equalsIgnoreCase("admin")) {
            logger.log(Level.INFO, "Gebruikersnaam gevonden (geen admin): {0}", username);
        } else if (username != null && username.equalsIgnoreCase("admin")) {
            logger.log(Level.FINE, "Admin gebruikersnaam gevonden: {0}", username);
        } else {
            logger.log(Level.WARNING, "Geen gebruikersnaam gevonden in het verzoek.");
        }

        return username;
    }
}

