import jakarta.servlet.http.HttpServletRequest;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ClassX {

    public String getAndValidateXForwardedFor(HttpServletRequest request) {
        String xForwardedForHeader = request.getHeader("X-Forwarded-For");

        if (xForwardedForHeader == null || xForwardedForHeader.isEmpty()) {
            // Depending on requirements, you might want to throw an exception here
            // or return null/empty string, as the header is missing.
            // For this specific requirement "if not local, throw exception",
            // if it's missing, it's not explicitly non-local.
            // Let's assume for now, if it's missing, we still proceed but may
            // not have an IP to validate. If validation is mandatory, uncomment below:
            // throw new IllegalArgumentException("X-Forwarded-For header is missing.");
            return null; // Or throw an exception if the header is mandatory
        }

        // X-Forwarded-For can contain a comma-separated list of IPs.
        // The client's IP is typically the first one in the list.
        String clientIp = xForwardedForHeader.split(",")[0].trim();

        try {
            InetAddress address = InetAddress.getByName(clientIp);

            if (address.isLoopbackAddress() || address.isSiteLocalAddress()) {
                // It's a local IP, allow it.
                return xForwardedForHeader;
            } else {
                // It's not a local IP, throw an exception.
                throw new SecurityException("Access denied: Non-local X-Forwarded-For IP address detected: " + clientIp);
            }
        } catch (UnknownHostException e) {
            // The provided IP address in the header is malformed or unresolvable.
            throw new IllegalArgumentException("Invalid IP address in X-Forwarded-For header: " + clientIp, e);
        }
    }
}
