            int exitCode = process.waitFor();

            if (exitCode != 0) {
                // Si el comando falla, lanzar una excepción o registrar el error
                throw new IOException("Command failed with exit code " + exitCode + ". Output: " + stdout /* + " Error: " + stderr */);
            }

            return stdout;

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("Command execution interrupted", e);
        }
    }
